const textbookFigures = [
  {group:'basin',id:'2.1',image:'fig-2-01.png',title:'全球地形与海底地形',summary:'全球高程—水深图把陆地、陆架、深海盆地、洋中脊和海沟放在同一垂向尺度上。海洋并不是平坦水盆，而是由板块构造塑造的起伏系统。',points:['蓝色越深通常表示水深越大，浅蓝色沿大陆边缘勾勒出大陆架。','大洋中央连续的浅色带对应洋中脊；狭长的深色带多对应海沟。','30角秒分辨率约为1 km量级，但不同区域的真实信息仍取决于船测与重力反演覆盖。'],research:'东海位于宽广大陆架上，水深和坡度控制潮汐、陆架波、近岸环流及海浪变形。'},
  {group:'basin',id:'2.2',image:'fig-2-02.png',title:'地球表面的高程—水深分布',summary:'面积分布呈明显“双峰”：陆地集中在接近海平面的正高程，海底集中在约4 km深处，中间的大陆坡面积较小。',points:['图示平均陆地高度约743 m，平均海深约3734 m，中位海深约4083 m。','深于8 km的海沟只占极小面积，不能代表典型海底。','双峰结构反映大陆地壳与大洋地壳厚度、密度和等静力状态的差异。'],research:'给模式设置地形或解释观测站代表性时，应区分陆架、陆坡和深海盆地，不能只用“平均海深”。'},
  {group:'basin',id:'2.3',image:'fig-2-03.png',title:'海洋岩石圈年龄',summary:'洋中脊处生成的新洋壳最年轻，年龄随离开扩张中心而增大；老洋壳最终在俯冲带被消耗，因此海洋岩石圈远年轻于多数大陆。',points:['近洋中脊的年龄接近0，平行于脊轴的年龄带记录海底扩张。','太平洋西部保留较老洋壳，周缘海沟对应俯冲消亡边界。','黑线表示板块边界；年龄带的偏移可识别转换断层。'],research:'构造年龄影响海底热流和盆地深度，但近岸潮汐与陆架波更直接受现代地形控制。'},
  {group:'basin',id:'2.4',image:'fig-2-04.png',title:'快、慢速扩张洋中脊地貌',summary:'东太平洋海隆扩张快，轴部较宽缓；大西洋中脊扩张慢，中央裂谷和断裂地貌更粗糙。扩张速率改变岩浆供给、断层活动和海底起伏。',points:['左图快扩张脊的脊顶宽、起伏相对平滑。','右图慢扩张脊可见明显轴谷与密集断裂条带。','两图尺度相同，约1000 km，便于直接比较地貌纹理。'],research:'海底粗糙度会影响深海混合、内潮散射和声传播，是能量耗散参数化的重要背景。'},
  {group:'basin',id:'2.5',image:'fig-2-05.png',title:'海盆地貌单元与实测剖面',summary:'示意图与南太平洋实测水深剖面展示从大陆架、陆坡到深海平原、洋中脊、海山和海沟的完整海盆结构。',points:['大陆架浅而缓，大陆坡陡，坡脚外侧可形成大陆隆。','深海平原整体平坦，但其上分布海山和深海丘陵。','洋中脊抬升数千米；俯冲边界形成狭窄而深的海沟。'],research:'东海近岸研究最相关的是大陆架宽度、陆坡位置和海槽，它们约束潮波传播及跨陆架交换。'},
  {group:'basin',id:'2.6',image:'fig-2-06.png',title:'全球海底平均坡度',summary:'大部分深海平原坡度很小，较大坡度集中在大陆坡、海沟、洋中脊和海山附近，说明海底动力边界具有强烈空间非均匀性。',points:['图中亮暗表示平均坡度而非水深，不能把陡坡误读为深水。','陆缘和板块边界形成连续高坡度带。','低分辨率插值会平滑陡峭地形，低估局地坡度。'],research:'坡度决定地形波、内潮和沿岸俘获波的模态结构，制作东海地形特征时应保留陆坡梯度。'},
  {group:'basin',id:'2.7',image:'fig-2-07.png',title:'1929年大浅滩浊流证据',summary:'纽芬兰以南地震触发沉积物重力流，沿坡向深海传播并先后切断海底电缆；电缆断裂时间提供了浊流移动的间接观测。',points:['浊流是高含沙、密度大于周围海水的底层重力流。','顺序断缆证明扰动不是同一时刻的远程地震破坏，而是沿海底传播。','浊流可搬运大量沉积物并形成深海扇，也会威胁海底工程。'],research:'近岸观测与海缆数据出现突变时，需要区分水动力异常、沉积物过程与仪器故障。'},
  {group:'basin',id:'2.8',image:'fig-2-08.png',title:'太平洋海盆地形',summary:'太平洋面积最大且边缘海沟密集，东太平洋海隆偏东，西部发育岛弧—海沟系统和众多边缘海，海盆结构明显不对称。',points:['东太平洋海隆是快速扩张中心。','西太平洋海沟最深，反映太平洋板块向周缘俯冲。','海山链记录板块越过热点的运动历史。'],research:'东海通过琉球岛弧与西太平洋相连，黑潮沿陆坡流动，地形对陆架交换至关重要。'},
  {group:'basin',id:'2.9',image:'fig-2-09.png',title:'大西洋海盆地形',summary:'大西洋中脊大致位于海盆中央，海底年龄和地形在两侧较对称；多数边缘为被动大陆边缘，宽陆架与大陆隆较发育。',points:['中央洋中脊从北冰洋延伸至南大洋。','海盆两侧对称扩张是板块分离的重要证据。','海沟数量少于太平洋，但局地仍有岛弧和俯冲系统。'],research:'大西洋经向翻转环流与南北向海盆形状相关，可与太平洋的深水更新形成对照。'},
  {group:'basin',id:'2.10',image:'fig-2-10.png',title:'印度洋海盆地形',summary:'印度洋由多条洋中脊分割，并在中部形成三联点；北部受亚洲大陆封闭，海盆几何与季风强迫共同塑造独特环流。',points:['中印度洋脊、西南印度洋脊和东南印度洋脊构成扩张系统。','爪哇—巽他海沟标志印度—澳大利亚板块向北俯冲。','图中关于季风的手写提示是课堂注释，不是原图数据层。'],research:'北印度洋季风风向半年反转，使上层环流季节性强，是风驱海洋响应的典型案例。'},
  {group:'basin',id:'2.11',image:'fig-2-11.png',title:'北冰洋海盆地形',summary:'北冰洋由广阔浅陆架、中央深海盆和多条海岭组成，并通过白令海峡、弗拉姆海峡及北欧海与其他大洋交换。',points:['欧亚大陆边缘拥有全球最宽广的陆架之一。','罗蒙诺索夫海岭等把中央盆地分隔成多个子海盆。','海冰、极夜、天气与后勤限制使历史观测稀疏。'],research:'海冰改变动量和热盐交换；窄海峡输运对北冰洋淡水收支和全球气候具有放大作用。'},
  {group:'basin',id:'2.12',image:'fig-2-12.png',title:'南大洋与南极洲周边地形',summary:'南大洋环绕南极洲连续分布，德雷克海峡连接各大洋，使南极绕极流能够沿纬向贯通；海冰和冰间湖呈强季节变化。',points:['陆块阻挡较少是形成强大绕极流的几何条件。','海岭与海峡会引导或收缩流路并增强混合。','沿岸潜水区和开阔水冰间湖可发生强烈海气交换与致密水形成。'],research:'南大洋是全球海洋热量、碳和深层水交换的枢纽，可作为东海陆架局地过程的尺度对照。'},

  {group:'properties',id:'3.1',image:'fig-3-01.png',title:'温度、盐度与海水密度',summary:'等密度线显示海水密度随盐度增加而增大、随温度升高而减小。典型海洋温盐范围位于图中狭窄区域。',points:['σt是密度减去1000 kg m⁻³后的数值。','高盐海水的最大密度温度低于其冰点，因此海水通常先结冰，不会像淡水湖那样在4°C出现密度最大层。','状态方程是非线性的，同样温盐变化在不同背景状态下产生不同密度响应。'],research:'潮位、内波和层结分析必须从温盐计算密度，不能只看温度剖面。'},
  {group:'properties',id:'3.2',image:'fig-3-02.png',title:'压力与深度的近似关系',summary:'海洋中压力随深度近似线性增加；常用经验是1 dbar约对应1 m水深，但精确换算还受纬度、重力和密度影响。',points:['图示北太平洋站位从海面到约6000 m基本呈直线。','海表压力通常记为0 dbar的海洋学表压。','CTD直接测压力，再换算为深度或作为垂向坐标。'],research:'处理剖面数据时应保留pressure与depth的区别，尤其在高精度动力高度计算中。'},
  {group:'properties',id:'3.3',image:'fig-3-03.png',title:'实测温度、位温、电导率与盐度剖面',summary:'东北太平洋剖面展示实测温度T、位温θ、电导率和盐度的垂向变化。位温去除了水团绝热升降造成的压缩增温。',points:['深层T通常略高于θ，差值随压力增大。','电导率同时受温度、盐度和压力影响，不能直接等同于盐度。','盐度由电导率比、温度和压力按标准算法计算。'],research:'比较不同深度水团时优先使用位温或保守温度，并采用TEOS‑10一致处理。'},
  {group:'properties',id:'3.4',image:'fig-3-04.png',title:'压力压缩导致的密度增加',summary:'即使水团在海表具有固定温度0°C和盐度35，随压力增加其原位密度仍会显著增大，这是海水可压缩性的结果。',points:['图中从海表约1028 kg m⁻³增至5000 dbar处约1050 kg m⁻³。','原位密度随深度增加不一定代表稳定层结，因为其中含有纯压缩效应。','判断稳定性需把水团绝热移到共同参考压力。'],research:'计算浮力频率、地转流和水团密度时，应使用位密度或TEOS‑10中适当变量。'},
  {group:'properties',id:'3.5',image:'fig-3-05.png',title:'参考压力与位密度',summary:'同一水团相对于海表0 dbar和深层4000 dbar计算的位密度不同，说明位密度必须明确参考压力。',points:['σ0适合上层海洋，σ2、σ4常用于更深层。','跨越很大深度范围时，固定参考压力的位密度面可能偏离中性面。','两水团混合路径与弯曲等密度线也体现海水状态方程非线性。'],research:'做深层水团分类或EOF前的密度异常计算时，应写清参考压力和温盐标准。'},
  {group:'properties',id:'3.6',image:'fig-3-06.png',title:'位密度与浮力频率剖面',summary:'位密度随深度增加表示稳定层结；Brunt–Väisälä频率N量化垂向位移后水团的回复振荡速度。',points:['上层密度梯度大，N通常较高，对应较短浮力周期。','深海密度变化缓慢，N较低，层结较弱。','稳定层结要求N²>0；若N²<0则可能发生对流翻转。'],research:'N控制内波传播、第一斜压变形半径和沿岸俘获波模态，是东海内潮研究的关键剖面量。'},
  {group:'properties',id:'3.7',image:'fig-3-07.png',title:'声速的温盐压贡献',summary:'海水声速由温度、盐度和压力共同决定：升温、增盐与增压通常都会提高声速，但温度随深度降低和压力随深度增加相互竞争。',points:['表层温跃层中温度下降常使声速降低。','深层压力效应占优，声速随深度再次升高。','二者共同形成声速最小层，即深海声道轴。'],research:'声速剖面决定声呐和水声通信路径，也影响ADCP及声学观测的传播修正。'},
  {group:'properties',id:'3.8',image:'fig-3-08.png',title:'海洋中的声线折射',summary:'声线按照声速梯度连续折射，并趋向声速较低的区域；声速极小层可把声能限制在深海声道内传播很远。',points:['浅层声源可能形成表面声道或出现声影区。','深海声道中的声线围绕声速最小层上下振荡。','路径取决于初始发射角和整个声速剖面，而不只是水深。'],research:'布设水声观测或解释远距离声信号时，需要同期温盐剖面计算声速。'},
  {group:'properties',id:'3.9',image:'fig-3-09.png',title:'海水光学过程框架',summary:'太阳入射、海况和海底边界与海水固有光学性质共同决定辐射场，并表现为卫星可观测的表观光学性质。',points:['固有光学性质主要是吸收和散射，与外部光场无关。','表观光学量包括上/下行辐照度、反射率和PAR，受太阳角度与海况影响。','吸收产生加热，PAR驱动光合作用，出水辐亮度形成海色遥感信号。'],research:'利用卫星海色研究近岸水体时，需同时考虑悬沙、叶绿素、CDOM和大气校正。'},
  {group:'properties',id:'3.10',image:'fig-3-10.png',title:'光谱衰减与光在海水中的穿透',summary:'清洁大洋水在蓝—绿波段衰减最弱、穿透最深；浑浊近岸水因颗粒与有色物质吸收散射增强，透光深度显著减小。',points:['红光被水快速吸收，只能穿透很浅。','清洁水体的透光窗口偏蓝，浑浊水体常向绿光移动。','图中110、30、10、1 m曲线说明不同水质下光谱能量随深度迅速改变。'],research:'东海近岸高浑浊水会降低遥感反射率解释的通用性，算法需分水体类型验证。'},
  {group:'properties',id:'3.11',image:'fig-3-11.png',title:'卫星接收辐亮度与大气校正',summary:'卫星传感器接收的总辐亮度大部分来自大气散射，真正携带海色信息的离水辐亮度只占很小部分，因此大气校正是海色反演的核心。',points:['顶层大气信号比水体目标信号可高一个数量级以上。','校正误差会直接传递到叶绿素、悬沙等产品。','近岸气溶胶复杂、邻近效应强，通常比开阔海更难校正。'],research:'使用海色产品训练模型时，应保留质量标志并检查近岸异常，避免把大气残差当作海洋变化。'},
  {group:'properties',id:'3.12',image:'fig-3-12.png',title:'两类冰间湖形成机制',summary:'冰间湖是海冰覆盖区持续或反复出现的开阔水面，可由风驱冰外输的潜热过程或海洋向上供热的感热过程维持。',points:['潜热冰间湖：风把新生海冰移走，持续结冰和盐析促成致密水。','感热冰间湖：潮汐或地形混合把较暖深层水带到表面并融冰。','开阔水增强海气热量、水汽和动量交换。'],research:'冰间湖是高纬深水形成与海气交换热点，也展示了表面边界条件如何改变水团。'},

  {group:'structure',id:'4.1',image:'fig-4-01-surface-temperature.png',title:'全球冬季海表温度',summary:'海表温度总体随纬度降低，但受西边界流、上升流、海陆分布和季节影响而出现强烈经向与东西向差异。',points:['热带暖池最暖，高纬与海冰边缘最冷。','湾流和黑潮把暖水向极输送，形成密集等温线和强锋面。','东部边界上升流使同纬度海温偏低。'],research:'海温锋面与近岸风、波浪和海气通量耦合，适合与潮位、海浪预测共同作为环境特征。'},
  {group:'structure',id:'SST‑SAT',image:'satellite-sst.png',title:'卫星海表温度视图',summary:'卫星提供准全球、高空间分辨率的SST，能显示锋面、涡旋和上升流；不同传感器在分辨率、云影响和覆盖范围之间存在权衡。',points:['红外SST分辨率高但受云遮挡。','微波SST可穿云，但分辨率较粗，近岸和强降雨条件下误差较大。','卫星只测“表皮”或次表层温度，与浮标深度温度并非完全相同。'],research:'深度学习使用SST时应记录传感器、昼夜、云掩膜和观测深度定义，防止数据源切换造成偏差。'},
  {group:'structure',id:'SST‑RANGE',image:'annual-range-sst.png',title:'海表温度年较差',summary:'年较差在中高纬和西北大洋最大，在热带开阔海洋较小；其空间分布由季节性辐射、混合层深度、海流和海冰共同控制。',points:['夏季浅混合层升温快，冬季冷却和风混合使混合层加深。','陆地邻近、季风和西边界流区季节变化可显著增强。','季节信号随深度快速衰减，深海几乎感受不到年周期。'],research:'模型切分应覆盖完整季节循环；若训练与测试季节分布不同，可能产生虚假的预测优势。'},
  {group:'structure',id:'ATL‑20W',image:'atlantic-section.png',title:'大西洋20°W温盐密度断面',summary:'经向断面显示暖水集中于上层、永久温跃层下方为冷深水；盐度和密度结构记录副热带蒸发、高纬深水形成及南北半球水团交换。',points:['上层等温线倾斜与环流和风驱温跃层有关。','北大西洋表层和中层总体较咸；深层分布受北大西洋深水影响。','南极底层水从南方进入最深处，表现为低温高密度水。'],research:'温盐密度三图需联合判读，单独用温度很难区分相似温度但来源不同的水团。'},
  {group:'structure',id:'PAC‑150W',image:'pacific-section.png',title:'太平洋150°W温盐密度断面',summary:'太平洋上层温跃层显著，赤道和副热带结构受风驱环流控制；北太平洋表层偏淡，深水主要从南方和其他海盆输入。',points:['热带暖水层薄，温跃层随纬度和环流起伏。','北太平洋高纬降水多且无强深水形成，表层盐度较低。','深层水团沿全球翻转环流路径逐渐变老并发生性质改变。'],research:'太平洋断面可作为ENSO EOF空间模态的三维背景，但二维EOF不能直接代表完整翻转环流。'},
  {group:'structure',id:'IND‑90E',image:'indian-section.png',title:'印度洋90°E温盐密度断面',summary:'印度洋断面显示热带暖水、南半球副热带温跃层和来自南大洋的深底层水；北部表层性质又受到季风、降水和海盆封闭的影响。',points:['温盐跃层共同决定密跃层强度。','深层水主要经南部通道更新，北印度洋没有高纬深水源。','局地高盐或低盐水可沿等密度面向海洋内部俯冲传播。'],research:'季风造成强季节非平稳性，使用EOF或机器学习时应先判断是否需要分季节建模。'},
  {group:'structure',id:'SSS',image:'surface-salinity.png',title:'全球冬季表层盐度',summary:'表层盐度反映蒸发、降水、径流、结冰融冰和环流的综合作用：副热带蒸发带高盐，赤道多雨带和高纬海区偏淡。',points:['盐度高值通常位于20°–30°副热带E>P区域。','ITCZ、河口和高纬P>E区域盐度低。','大西洋整体比太平洋更咸，与跨盆水汽输送和海盆淡水收支有关。'],research:'东海近岸盐度受长江径流和季风强烈调制，是密度分层、锋面和水位响应的重要预测因子。'},
  {group:'structure',id:'SSD',image:'surface-density.png',title:'全球冬季表层密度',summary:'表层密度由温度与盐度共同决定，总体从暖热带向冷高纬增大；北大西洋与南极周边存在适合深水形成的高密度表层水。',points:['低纬温度效应占主导，暖水密度低。','高纬盐度差异变得关键：北太平洋因较淡而比北大西洋难形成深水。','密度而非单独温度决定浮力、层结与对流潜势。'],research:'近岸深度学习若要保持物理一致性，可把由温盐计算的密度或浮力通量作为辅助变量。'},
  {group:'structure',id:'PYC',image:'pycnocline.png',title:'密跃层及其纬向差异',summary:'密跃层是密度随深度快速增加的层。热带—副热带上层密跃层强而浅，高纬水柱表层密度更高、上下密度差较小，永久密跃层通常较弱。',points:['图中不同纬度剖面显示相同深度范围内密度梯度差异。','密跃层通常与温跃层相关，但降水、径流或盐跃层也可主导密度变化。','密跃层以下深海密度变化小，却仍保持稳定层结。'],research:'密跃层深度影响内波相速、混合层热容量与上层海洋可预报性，应作为模型分层特征。'}
];

const groupNames={all:'全部图解',basin:'第2章 · 海盆地形',properties:'第3章 · 海水物性',structure:'温盐密度结构'};
const textbookGrid=document.getElementById('textbookGrid');
const textbookFilters=document.getElementById('textbookFilters');

function renderTextbook(group='all'){
  const selected=group==='all'?textbookFigures:textbookFigures.filter(item=>item.group===group);
  textbookGrid.innerHTML=selected.map(item=>`<article class="figure-card">
    <a class="figure-image" href="assets/textbook/${item.image}" target="_blank" rel="noopener" aria-label="打开 ${item.id} 原图">
      <img src="assets/textbook/${item.image}" alt="${item.id} ${item.title}" loading="lazy">
      <span>点击查看原图 ↗</span>
    </a>
    <div class="figure-copy"><div class="figure-id">FIGURE ${item.id}</div><h3>${item.title}</h3><p>${item.summary}</p>
      <details><summary>展开读图重点</summary><ul>${item.points.map(point=>`<li>${point}</li>`).join('')}</ul><p class="research-link"><b>与你的研究：</b>${item.research}</p></details>
    </div></article>`).join('');
  [...textbookFilters.querySelectorAll('button')].forEach(button=>button.classList.toggle('active',button.dataset.group===group));
}

Object.entries(groupNames).forEach(([key,label])=>{
  const count=key==='all'?textbookFigures.length:textbookFigures.filter(item=>item.group===key).length;
  const button=document.createElement('button');
  button.type='button';button.dataset.group=key;button.textContent=`${label} · ${count}`;
  button.addEventListener('click',()=>renderTextbook(key));
  textbookFilters.appendChild(button);
});
renderTextbook();

